CREATE   PROCEDURE dbo.usp_DieuChinhDiemDoiTra
    @SoPhieuDT VARCHAR(30), @KetQua NVARCHAR(40)=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    IF DB_NAME()<>N'FashionStoreDB' THROW 57010,N'FashionStoreDB database required.',1;
    IF NULLIF(LTRIM(RTRIM(@SoPhieuDT)),'') IS NULL THROW 57011,N'Return ID required.',1;
    DECLARE @SoHD VARCHAR(30),@MaKH VARCHAR(20),@Loai VARCHAR(20),@Status VARCHAR(20),@DaXuLy BIT,
        @Ban DECIMAL(28,2),@PrevDelta DECIMAL(28,2),@NewDelta DECIMAL(28,2),
        @EarnCurrent BIGINT,@EarnExpectedPrev BIGINT,@EarnExpectedNew BIGINT,
        @Diff BIGINT,@Balance BIGINT,@LedgerBalance BIGINT,@EarnCount INT;
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT @SoHD=SoHD FROM dbo.PhieuDoiTra WHERE SoPhieuDT=@SoPhieuDT;
        IF @SoHD IS NULL THROW 57012,N'Return request not found.',1;
        SELECT @MaKH=MaKH,
           @Ban=CONVERT(DECIMAL(28,2),TongTienHang)-ChietKhau-TienKhuyenMai-TienGiamDiem
        FROM dbo.HoaDon WITH(UPDLOCK,HOLDLOCK) WHERE SoHD=@SoHD;
        IF @MaKH IS NULL OR @Ban IS NULL OR @Ban<0 THROW 57013,N'Original paid invoice or net merchandise base invalid.',1;
        SELECT @Status=TrangThai,@Loai=HinhThucXuLy,@DaXuLy=DiemDaXuLy
        FROM dbo.PhieuDoiTra WITH(UPDLOCK,HOLDLOCK) WHERE SoPhieuDT=@SoPhieuDT AND SoHD=@SoHD;
        IF @DaXuLy=1
        BEGIN
            SET @KetQua=N'DA_XU_LY_TRUOC';
            COMMIT TRANSACTION;
            RETURN;
        END;
        IF @Status<>'HOAN_TAT' OR @Loai NOT IN ('DOI','TRA')
            THROW 57014,N'Only completed single-mode DOI/TRA requests supported.',1;
        IF EXISTS(SELECT 1 FROM dbo.PhieuDoiTra WHERE SoHD=@SoHD AND TrangThai='HOAN_TAT'
                   AND SoPhieuDT<>@SoPhieuDT AND DiemDaXuLy=0)
            THROW 57015,N'Another completed return has points pending; process in correct order.',1;
        IF EXISTS(SELECT 1 FROM dbo.PhieuDoiTra p JOIN dbo.ChiTietDoiTra d ON d.SoPhieuDT=p.SoPhieuDT
                  WHERE p.SoHD=@SoHD AND p.TrangThai='HOAN_TAT' AND (p.DiemDaXuLy=1 OR p.SoPhieuDT=@SoPhieuDT)
                    AND (p.HinhThucXuLy NOT IN ('DOI','TRA') OR d.GiaTriHangTraThucTe IS NULL
                         OR d.GiaTriHangTraThucTe<0 OR
                          (p.HinhThucXuLy='DOI' AND (d.GiaTriHangDoi IS NULL OR d.GiaTriHangDoi<0))))
            THROW 57016,N'Return line lacks a trustworthy net amount.',1;
        SELECT @Balance=DiemTichLuy FROM dbo.KhachHang WITH(UPDLOCK,HOLDLOCK) WHERE MaKH=@MaKH;
        SELECT @LedgerBalance=COALESCE(SUM(CONVERT(BIGINT,SoDiemThayDoi)),0)
        FROM dbo.LichSuDiem WITH(HOLDLOCK) WHERE MaKH=@MaKH;
        IF @Balance IS NULL OR @Balance<>@LedgerBalance
            THROW 57017,N'Customer balance and historical point ledger do not reconcile.',1;
        SELECT @EarnCount=COUNT(*),@EarnCurrent=COALESCE(SUM(CONVERT(BIGINT,SoDiemThayDoi)),0)
        FROM dbo.LichSuDiem WHERE SoHD=@SoHD AND LoaiGiaoDich IN ('TICH','DIEU_CHINH')
              AND (LoaiGiaoDich='DIEU_CHINH' OR SoDiemThayDoi>0);
        IF (SELECT COUNT(*) FROM dbo.LichSuDiem WHERE SoHD=@SoHD AND LoaiGiaoDich='TICH')<>1
            THROW 57018,N'Invoice must have exactly one original earned-point record.',1;
        IF EXISTS(SELECT 1 FROM dbo.LichSuDiem WHERE SoHD=@SoHD AND LoaiGiaoDich='HOAN')
            THROW 57019,N'Unexpected legacy point reversals; reconcile manually.',1;
        SELECT @PrevDelta=COALESCE(SUM(
             CASE WHEN p.HinhThucXuLy='DOI' THEN CONVERT(DECIMAL(28,2),d.GiaTriHangDoi)-d.GiaTriHangTraThucTe
                  ELSE -CONVERT(DECIMAL(28,2),d.GiaTriHangTraThucTe) END),0)
        FROM dbo.PhieuDoiTra p JOIN dbo.ChiTietDoiTra d ON d.SoPhieuDT=p.SoPhieuDT
        WHERE p.SoHD=@SoHD AND p.TrangThai='HOAN_TAT' AND p.DiemDaXuLy=1;
        IF @Ban+@PrevDelta<0 THROW 57020,N'Past completed returns exceed paid merchandise amount.',1;
        SET @EarnExpectedPrev=CONVERT(BIGINT,FLOOR((@Ban+@PrevDelta)/10000));
        IF @EarnCurrent<>@EarnExpectedPrev
            THROW 57021,N'Invoice points do not match new no-shipping policy. Reconcile HD001 seed first.',1;
        SELECT @NewDelta=COALESCE(SUM(
             CASE WHEN @Loai='DOI' THEN CONVERT(DECIMAL(28,2),GiaTriHangDoi)-GiaTriHangTraThucTe
                  ELSE -CONVERT(DECIMAL(28,2),GiaTriHangTraThucTe) END),0)
        FROM dbo.ChiTietDoiTra WHERE SoPhieuDT=@SoPhieuDT;
        IF @Ban+@PrevDelta+@NewDelta<0 THROW 57022,N'Return value exceeds paid merchandise.',1;
        SET @EarnExpectedNew=CONVERT(BIGINT,FLOOR((@Ban+@PrevDelta+@NewDelta)/10000));
        SET @Diff=@EarnExpectedNew-@EarnCurrent;
        IF @Diff NOT BETWEEN -2147483647 AND 2147483647 THROW 57023,N'Point delta out of INT range.',1;
        IF @Balance+@Diff<0 OR @Balance+@Diff>2147483647
            THROW 57024,N'Not enough current points to reverse this refund; manual settlement required.',1;
        IF @Diff<>0
        BEGIN
            UPDATE dbo.KhachHang SET DiemTichLuy=CONVERT(INT,@Balance+@Diff)
            WHERE MaKH=@MaKH AND DiemTichLuy=CONVERT(INT,@Balance);
            IF @@ROWCOUNT<>1 THROW 57025,N'Concurrent customer point update rejected.',1;
            INSERT dbo.LichSuDiem(MaKH,SoHD,SoPhieuDT,LoaiGiaoDich,SoDiemThayDoi,GhiChu)
            VALUES(@MaKH,@SoHD,@SoPhieuDT,'DIEU_CHINH',CONVERT(INT,@Diff),
                N'Post-discount merchandise only (excluding ship): recalculated after return');
        END;
        UPDATE dbo.PhieuDoiTra SET DiemDaXuLy=1 WHERE SoPhieuDT=@SoPhieuDT AND DiemDaXuLy=0;
        IF @@ROWCOUNT<>1 THROW 57026,N'Point completion marker changed concurrently.',1;
        SET @KetQua=N'DA_XU_LY_MOI';
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

CREATE   PROCEDURE dbo.usp_HoanTatDoiHangNgangGia
    @SoPhieuDT VARCHAR(30),
    @MaNVDuyet VARCHAR(20),
    @DaKiemTraHang BIT,
    @XacNhanKhongNgoaiLe BIT,
    @KetQua NVARCHAR(30) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF DB_NAME() <> N'FashionStoreDB'
        THROW 55002, N'Procedure target must be FashionStoreDB.', 1;
    IF NULLIF(LTRIM(RTRIM(@SoPhieuDT)),'') IS NULL
       OR NULLIF(LTRIM(RTRIM(@MaNVDuyet)),'') IS NULL
        THROW 55003, N'Return reference and approver are required.', 1;
    IF ISNULL(@DaKiemTraHang,0) <> 1 OR ISNULL(@XacNhanKhongNgoaiLe,0) <> 1
        THROW 55004, N'Physical inspection and exception-policy confirmation are required.', 1;

    DECLARE @SoHD VARCHAR(30), @TinhTrang VARCHAR(20), @HinhThuc VARCHAR(20),
            @NgayYeuCau DATETIME2(0), @NgayBan DATETIME2(0),
            @TTDon VARCHAR(20), @TTGiao VARCHAR(20), @TTThanhToan VARCHAR(20),
            @MaChiTietDT BIGINT, @MaSKUCu VARCHAR(40), @MaSKUMoi VARCHAR(40),
            @SL INT, @SLMoi INT, @GiaTriTra DECIMAL(18,2), @GiaTriDoi DECIMAL(18,2),
            @SoTienHoan DECIMAL(18,2), @SoTienThuThem DECIMAL(18,2),
            @SoDong INT, @TonCu INT, @TonMoi INT;

    BEGIN TRY
        BEGIN TRANSACTION;
        -- Serialize all return operations that share one original invoice.
        -- Lock invoice before request to keep lock ordering consistent across returns.
        SELECT @SoHD = SoHD
        FROM dbo.PhieuDoiTra
        WHERE SoPhieuDT = @SoPhieuDT;
        IF @SoHD IS NULL THROW 55005, N'Return request not found.', 1;

        SELECT @NgayBan=NgayLap, @TTDon=TrangThaiHoaDon,
               @TTGiao=TrangThaiGiaoHang, @TTThanhToan=TrangThaiThanhToan
        FROM dbo.HoaDon WITH (UPDLOCK,HOLDLOCK)
        WHERE SoHD=@SoHD;
        IF @NgayBan IS NULL THROW 55006, N'Original invoice missing.', 1;

        SELECT @TinhTrang=TrangThai, @HinhThuc=HinhThucXuLy,
               @NgayYeuCau=NgayLap, @SoTienHoan=SoTienHoan,
               @SoTienThuThem=SoTienThuThem
        FROM dbo.PhieuDoiTra WITH (UPDLOCK,HOLDLOCK)
        WHERE SoPhieuDT=@SoPhieuDT AND SoHD=@SoHD;
        IF @TinhTrang IS NULL THROW 55007, N'Return request was concurrently removed.', 1;
        IF @HinhThuc <> 'DOI'
            THROW 55008, N'This pilot supports exchanges only, not refunds or mixed returns.', 1;

        SELECT @SoDong=COUNT(*)
        FROM dbo.ChiTietDoiTra WHERE SoPhieuDT=@SoPhieuDT;
        IF @SoDong<>1
            THROW 55009, N'This pilot supports exactly one exchanged SKU line.', 1;

        SELECT @MaChiTietDT=MaChiTietDT, @MaSKUCu=MaSKU, @MaSKUMoi=MaSKUMoi,
               @SL=SoLuong, @SLMoi=SoLuongMoi,
               @GiaTriTra=GiaTriHangTraThucTe, @GiaTriDoi=GiaTriHangDoi
        FROM dbo.ChiTietDoiTra WITH (UPDLOCK,HOLDLOCK)
        WHERE SoPhieuDT=@SoPhieuDT AND LoaiGiaoDich='DOI';
        IF @MaChiTietDT IS NULL OR @MaSKUMoi IS NULL OR @MaSKUCu=@MaSKUMoi
           OR @SL IS NULL OR @SL<=0 OR @SLMoi<>@SL
            THROW 55010, N'Exchange line is invalid or SKU/quantity not supported.', 1;

        -- Idempotent retry after a confirmed completion: verify complete ledger, do not repeat.
        IF @TinhTrang='HOAN_TAT'
        BEGIN
            IF (SELECT COUNT(*) FROM dbo.LichSuTonKho
                WHERE MaChungTu=@SoPhieuDT AND Nguon IN ('TRA','DOI'))<>2
               OR NOT EXISTS (SELECT 1 FROM dbo.LichSuTonKho
                   WHERE MaChungTu=@SoPhieuDT AND Nguon='TRA'
                     AND MaSKU=@MaSKUCu AND SoLuongThayDoi=@SL)
               OR NOT EXISTS (SELECT 1 FROM dbo.LichSuTonKho
                   WHERE MaChungTu=@SoPhieuDT AND Nguon='DOI'
                     AND MaSKU=@MaSKUMoi AND SoLuongThayDoi=-@SLMoi)
               OR NOT EXISTS (SELECT 1 FROM dbo.ChiTietDoiTra
                   WHERE MaChiTietDT=@MaChiTietDT AND DuDieuKienTaiBan=1)
                THROW 55011, N'Completed return has inconsistent ledger; investigate.', 1;
            SET @KetQua=N'DA_HOAN_TAT';
            COMMIT TRANSACTION;
            RETURN;
        END;

        IF @TinhTrang NOT IN ('CHO_DUYET','DA_DUYET')
            THROW 55012, N'Request is rejected or in an unsupported state.', 1;
        IF @TTDon<>'HOAN_TAT' OR @TTGiao<>'DA_GIAO'
           OR @TTThanhToan<>'DA_THANH_TOAN'
            THROW 55013, N'Original invoice must be paid, completed, and delivered.', 1;
        IF CAST(@NgayYeuCau AS DATE)<CAST(@NgayBan AS DATE)
           OR CAST(@NgayYeuCau AS DATE)>DATEADD(DAY,15,CAST(@NgayBan AS DATE))
            THROW 55014, N'Return request was not filed within the 15-day policy window.', 1;
        IF NOT EXISTS (SELECT 1 FROM dbo.NhanVien
                       WHERE MaNV=@MaNVDuyet AND TrangThai=1 AND MaQuyen='QL')
            THROW 55015, N'Approver must be an active manager (QL).', 1;
        IF @SoTienHoan<>0 OR @SoTienThuThem<>0
           OR @GiaTriTra IS NULL OR @GiaTriDoi IS NULL OR @GiaTriTra<>@GiaTriDoi
            THROW 55016, N'Only a zero-difference exchange is supported in this pilot.', 1;
        IF EXISTS (SELECT 1 FROM dbo.LichSuTonKho
                   WHERE MaChungTu=@SoPhieuDT AND Nguon IN ('TRA','DOI'))
            THROW 55017, N'This return already has stock movements.', 1;
        IF EXISTS (SELECT 1 FROM dbo.ThanhToan
                   WHERE SoPhieuDT=@SoPhieuDT AND LoaiGiaoDich='HOAN')
            THROW 55018, N'Refund transactions require a separate approval workflow.', 1;

        -- The returned SKU must belong to this invoice, and completed prior
        -- returns for the same invoice must not exceed the original quantity.
        IF NOT EXISTS
          (SELECT 1 FROM dbo.ChiTietHoaDon ct
           WHERE ct.SoHD=@SoHD AND ct.MaSKU=@MaSKUCu
             AND ct.SoLuong >= @SL +
               (SELECT COALESCE(SUM(ctd.SoLuong),0)
                FROM dbo.PhieuDoiTra pd
                JOIN dbo.ChiTietDoiTra ctd ON pd.SoPhieuDT=ctd.SoPhieuDT
                WHERE pd.SoHD=@SoHD AND pd.TrangThai='HOAN_TAT'
                  AND pd.SoPhieuDT<>@SoPhieuDT AND ctd.MaSKU=@MaSKUCu))
           THROW 55019, N'Returned SKU was not bought or has already been returned.', 1;
        IF NOT EXISTS (SELECT 1 FROM dbo.BienTheSanPham
                       WHERE MaSKU=@MaSKUMoi AND TrangThai=1)
            THROW 55020, N'Replacement SKU is missing or disabled.', 1;

        -- Both stock movements and the two ledger entries are atomic.
        UPDATE dbo.BienTheSanPham WITH (UPDLOCK)
           SET SoLuongTonKho=SoLuongTonKho+@SL
         WHERE MaSKU=@MaSKUCu
           AND CONVERT(BIGINT,SoLuongTonKho)+@SL<=2147483647;
        IF @@ROWCOUNT<>1 THROW 55021, N'Unable to restock inspected merchandise.', 1;
        SELECT @TonCu=SoLuongTonKho FROM dbo.BienTheSanPham WHERE MaSKU=@MaSKUCu;

        UPDATE dbo.BienTheSanPham WITH (UPDLOCK)
           SET SoLuongTonKho=SoLuongTonKho-@SLMoi
         WHERE MaSKU=@MaSKUMoi AND TrangThai=1 AND SoLuongTonKho>=@SLMoi;
        IF @@ROWCOUNT<>1 THROW 55022, N'Insufficient replacement SKU stock; fully rolled back.', 1;
        SELECT @TonMoi=SoLuongTonKho FROM dbo.BienTheSanPham WHERE MaSKU=@MaSKUMoi;

        INSERT dbo.LichSuTonKho
             (MaSKU,MaNV,Nguon,SoLuongThayDoi,TonSau,MaChungTu,GhiChu)
        VALUES
             (@MaSKUCu,@MaNVDuyet,'TRA',@SL,@TonCu,@SoPhieuDT,
              N'Customer return accepted for resale after physical inspection'),
             (@MaSKUMoi,@MaNVDuyet,'DOI',-@SLMoi,@TonMoi,@SoPhieuDT,
              N'Exchange replacement issued - equal net value');

        UPDATE dbo.ChiTietDoiTra
           SET DuDieuKienTaiBan=1,
               TinhTrang=N'Da kiem tra - du dieu kien tai ban'
         WHERE MaChiTietDT=@MaChiTietDT;
        UPDATE dbo.PhieuDoiTra
           SET TrangThai='HOAN_TAT',
               MaNVDuyet=@MaNVDuyet,
               NgayDuyet=COALESCE(NgayDuyet,SYSDATETIME()),
               NgayHoanTat=SYSDATETIME()
         WHERE SoPhieuDT=@SoPhieuDT;

        SET @KetQua=N'DA_HOAN_TAT_MOI';
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

CREATE   PROCEDURE dbo.usp_HoanTatDoiTraCoTien
    @SoPhieuDT VARCHAR(30),
    @MaNVDuyet VARCHAR(20),
    @DaKiemTraHang BIT,
    @XacNhanKhongNgoaiLe BIT,
    @KetQua NVARCHAR(30) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF DB_NAME() <> N'FashionStoreDB'
        THROW 56002, N'REVIEWED: expected production FashionStoreDB.', 1;
    IF NULLIF(LTRIM(RTRIM(@SoPhieuDT)),'') IS NULL
       OR NULLIF(LTRIM(RTRIM(@MaNVDuyet)),'') IS NULL
        THROW 56003, N'Missing return ID or approver.', 1;
    IF ISNULL(@DaKiemTraHang,0)<>1 OR ISNULL(@XacNhanKhongNgoaiLe,0)<>1
        THROW 56004, N'Physical inspection/policy confirmation required.', 1;

    DECLARE @SoHD VARCHAR(30), @TrangThai VARCHAR(20), @HinhThuc VARCHAR(20),
            @NgayLap DATETIME2(0), @NgayBan DATETIME2(0),
            @TTDon VARCHAR(20), @TTGiao VARCHAR(20), @TTThanh VARCHAR(20),
            @TienHoan DECIMAL(18,2), @TienThu DECIMAL(18,2),
            @ChiTietID BIGINT, @SKUCu VARCHAR(40), @SKUMoi VARCHAR(40),
            @SL INT, @SLMoi INT, @GT_Tra DECIMAL(18,2), @GT_Doi DECIMAL(18,2),
            @TonTra INT, @TonDoi INT, @SoDong INT,
            @LoaiTien VARCHAR(10), @TienCan DECIMAL(18,2), @SoGD INT;
    BEGIN TRY
        BEGIN TRANSACTION;
        -- Serialize all returns of an invoice before reading its aggregate returned quantity.
        SELECT @SoHD=SoHD FROM dbo.PhieuDoiTra WHERE SoPhieuDT=@SoPhieuDT;
        IF @SoHD IS NULL THROW 56005, N'Unknown return request.', 1;
        SELECT @NgayBan=NgayLap, @TTDon=TrangThaiHoaDon,
               @TTGiao=TrangThaiGiaoHang, @TTThanh=TrangThaiThanhToan
        FROM dbo.HoaDon WITH (UPDLOCK,HOLDLOCK) WHERE SoHD=@SoHD;
        IF @NgayBan IS NULL THROW 56006, N'Original invoice missing.', 1;

        SELECT @TrangThai=TrangThai, @HinhThuc=HinhThucXuLy,
               @NgayLap=NgayLap, @TienHoan=SoTienHoan, @TienThu=SoTienThuThem
        FROM dbo.PhieuDoiTra WITH (UPDLOCK,HOLDLOCK)
        WHERE SoPhieuDT=@SoPhieuDT AND SoHD=@SoHD;
        IF @TrangThai IS NULL THROW 56007, N'Return request disappeared.', 1;
        IF @HinhThuc NOT IN ('DOI','TRA')
            THROW 56008, N'Pilot supports DOI or TRA, not combined return.', 1;
        SELECT @SoDong=COUNT(*) FROM dbo.ChiTietDoiTra WHERE SoPhieuDT=@SoPhieuDT;
        IF @SoDong<>1 THROW 56009, N'Pilot supports exactly one item line.', 1;
        SELECT @ChiTietID=MaChiTietDT, @SKUCu=MaSKU, @SKUMoi=MaSKUMoi,
               @SL=SoLuong, @SLMoi=SoLuongMoi,
               @GT_Tra=GiaTriHangTraThucTe, @GT_Doi=GiaTriHangDoi
        FROM dbo.ChiTietDoiTra WITH (UPDLOCK,HOLDLOCK)
        WHERE SoPhieuDT=@SoPhieuDT;
        IF @ChiTietID IS NULL OR @SL IS NULL OR @SL<=0 OR @GT_Tra IS NULL OR @GT_Tra<=0
            THROW 56010, N'Invalid returned SKU, quantity or net refund basis.', 1;
        IF @HinhThuc='DOI'
        BEGIN
            IF @SKUMoi IS NULL OR @SKUMoi=@SKUCu OR @SLMoi IS NULL OR @SLMoi<=0
               OR @GT_Doi IS NULL OR @GT_Doi<=0 OR @GT_Doi=@GT_Tra
                THROW 56011, N'Unequal-price exchange requires a different SKU and nonzero delta.', 1;
            SET @TienThu=COALESCE(@TienThu,-1);
            SET @TienHoan=COALESCE(@TienHoan,-1);
            IF @TienThu<>CASE WHEN @GT_Doi>@GT_Tra THEN @GT_Doi-@GT_Tra ELSE 0 END
               OR @TienHoan<>CASE WHEN @GT_Tra>@GT_Doi THEN @GT_Tra-@GT_Doi ELSE 0 END
                THROW 56012, N'Exchange difference does not match return document.', 1;
        END
        ELSE
        BEGIN
            IF @SKUMoi IS NOT NULL OR @SLMoi IS NOT NULL OR @GT_Doi IS NOT NULL
               OR @TienHoan<>@GT_Tra OR @TienThu<>0
                THROW 56013, N'Refund-only request must have no replacement and correct refund.', 1;
        END;
        SET @LoaiTien=CASE WHEN @TienThu>0 THEN 'THU' ELSE 'HOAN' END;
        SET @TienCan=CASE WHEN @TienThu>0 THEN @TienThu ELSE @TienHoan END;

        -- Idempotency: completed request must have already settled money and complete ledgers.
        IF @TrangThai='HOAN_TAT'
        BEGIN
            IF (SELECT COUNT(*) FROM dbo.LichSuTonKho
                WHERE MaChungTu=@SoPhieuDT AND Nguon IN ('TRA','DOI'))
                   <> CASE WHEN @HinhThuc='DOI' THEN 2 ELSE 1 END
               OR NOT EXISTS(SELECT 1 FROM dbo.LichSuTonKho
                    WHERE MaChungTu=@SoPhieuDT AND Nguon='TRA' AND MaSKU=@SKUCu
                      AND SoLuongThayDoi=@SL)
               OR (@HinhThuc='DOI' AND NOT EXISTS(SELECT 1 FROM dbo.LichSuTonKho
                    WHERE MaChungTu=@SoPhieuDT AND Nguon='DOI' AND MaSKU=@SKUMoi
                      AND SoLuongThayDoi=-@SLMoi))
               OR (SELECT COUNT(*) FROM dbo.ThanhToan WHERE SoPhieuDT=@SoPhieuDT
                     AND TrangThai='THANH_CONG' AND LoaiGiaoDich=@LoaiTien
                     AND SoTien=@TienCan)<>1
                THROW 56014, N'Completed return has inconsistent ledger or payment.', 1;
            SET @KetQua=N'DA_HOAN_TAT';
            COMMIT TRANSACTION;
            RETURN;
        END;
        IF @TrangThai NOT IN ('CHO_DUYET','DA_DUYET')
            THROW 56015, N'Request rejected or unsupported status.', 1;
        IF @TTDon<>'HOAN_TAT' OR @TTGiao<>'DA_GIAO'
           OR @TTThanh NOT IN ('DA_THANH_TOAN','HOAN_MOT_PHAN')
            THROW 56016, N'Original invoice must be delivered and paid.', 1;
        IF CAST(@NgayLap AS DATE)<CAST(@NgayBan AS DATE)
           OR CAST(@NgayLap AS DATE)>DATEADD(DAY,15,CAST(@NgayBan AS DATE))
            THROW 56017, N'Outside the 15-day return-request window.', 1;
        IF NOT EXISTS(SELECT 1 FROM dbo.NhanVien
            WHERE MaNV=@MaNVDuyet AND TrangThai=1 AND MaQuyen='QL')
            THROW 56018, N'Approver must be an active manager.', 1;
        IF EXISTS(SELECT 1 FROM dbo.LichSuTonKho WHERE MaChungTu=@SoPhieuDT
                  AND Nguon IN ('TRA','DOI'))
            THROW 56019, N'Stock ledger already exists.', 1;
        IF EXISTS(SELECT 1 FROM dbo.LichSuDiem WHERE SoPhieuDT=@SoPhieuDT)
            THROW 56020, N'Points adjustment already linked; reconcile separately.', 1;
        IF NOT EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon ct
          WHERE ct.SoHD=@SoHD AND ct.MaSKU=@SKUCu AND ct.SoLuong>=@SL+
           (SELECT COALESCE(SUM(d.SoLuong),0)
            FROM dbo.PhieuDoiTra p JOIN dbo.ChiTietDoiTra d ON d.SoPhieuDT=p.SoPhieuDT
            WHERE p.SoHD=@SoHD AND p.TrangThai='HOAN_TAT'
              AND p.SoPhieuDT<>@SoPhieuDT AND d.MaSKU=@SKUCu))
            THROW 56021, N'Returned quantity exceeds original purchased quantity.', 1;
        IF @HinhThuc='DOI' AND NOT EXISTS(SELECT 1 FROM dbo.BienTheSanPham
            WHERE MaSKU=@SKUMoi AND TrangThai=1)
            THROW 56022, N'Replacement SKU is missing/inactive.', 1;

        -- Payment MUST have been independently verified by trusted payment integration.
        -- Database record alone cannot prove actual external transfer: TEST PILOT ONLY.
        SELECT @SoGD=COUNT(*) FROM dbo.ThanhToan WITH (UPDLOCK,HOLDLOCK)
        WHERE SoHD=@SoHD AND SoPhieuDT=@SoPhieuDT;
        IF @SoGD<>1 THROW 56023, N'Expected exactly one associated financial transaction.', 1;
        IF NOT EXISTS(SELECT 1 FROM dbo.ThanhToan
            WHERE SoHD=@SoHD AND SoPhieuDT=@SoPhieuDT AND LoaiGiaoDich=@LoaiTien
              AND SoTien=@TienCan AND TrangThai='THANH_CONG'
              AND NULLIF(LTRIM(RTRIM(MaGiaoDichNgoai)),'') IS NOT NULL)
            THROW 56024, N'Financial collection/refund is not verified as successful.', 1;
        IF @LoaiTien='HOAN' AND NOT EXISTS
            (SELECT 1 FROM dbo.ThanhToan hoan
             JOIN dbo.ThanhToan goc ON goc.MaThanhToan=hoan.MaThanhToanGoc
             WHERE hoan.SoHD=@SoHD AND hoan.SoPhieuDT=@SoPhieuDT
               AND hoan.LoaiGiaoDich='HOAN' AND hoan.TrangThai='THANH_CONG'
               AND goc.SoHD=@SoHD AND goc.LoaiGiaoDich='THU' AND goc.TrangThai='THANH_CONG')
            THROW 56025, N'Refund must reference an original successful collection.', 1;

        -- Protect against refunding more than collected for this invoice.
        IF @LoaiTien='HOAN' AND
             (SELECT COALESCE(SUM(SoTien),0) FROM dbo.ThanhToan
              WHERE SoHD=@SoHD AND LoaiGiaoDich='HOAN' AND TrangThai='THANH_CONG')
          > (SELECT COALESCE(SUM(SoTien),0) FROM dbo.ThanhToan
              WHERE SoHD=@SoHD AND LoaiGiaoDich='THU' AND TrangThai='THANH_CONG')
            THROW 56026, N'Total recorded refunds exceed recorded collections.', 1;

        UPDATE dbo.BienTheSanPham WITH (UPDLOCK)
           SET SoLuongTonKho=SoLuongTonKho+@SL
         WHERE MaSKU=@SKUCu AND CAST(SoLuongTonKho AS BIGINT)+@SL<=2147483647;
        IF @@ROWCOUNT<>1 THROW 56027, N'Cannot restock returned merchandise.', 1;
        SELECT @TonTra=SoLuongTonKho FROM dbo.BienTheSanPham WHERE MaSKU=@SKUCu;
        IF @HinhThuc='DOI'
        BEGIN
            UPDATE dbo.BienTheSanPham WITH (UPDLOCK)
               SET SoLuongTonKho=SoLuongTonKho-@SLMoi
             WHERE MaSKU=@SKUMoi AND TrangThai=1 AND SoLuongTonKho>=@SLMoi;
            IF @@ROWCOUNT<>1 THROW 56028, N'Insufficient replacement SKU stock.', 1;
            SELECT @TonDoi=SoLuongTonKho FROM dbo.BienTheSanPham WHERE MaSKU=@SKUMoi;
        END;
        INSERT dbo.LichSuTonKho(MaSKU,MaNV,Nguon,SoLuongThayDoi,TonSau,MaChungTu,GhiChu)
        VALUES(@SKUCu,@MaNVDuyet,'TRA',@SL,@TonTra,@SoPhieuDT,
               N'Tested return: merchandise physically inspected and fit for resale');
        IF @HinhThuc='DOI'
            INSERT dbo.LichSuTonKho(MaSKU,MaNV,Nguon,SoLuongThayDoi,TonSau,MaChungTu,GhiChu)
            VALUES(@SKUMoi,@MaNVDuyet,'DOI',-@SLMoi,@TonDoi,@SoPhieuDT,
                   N'Tested exchange: different net price, confirmed financial settlement');

        UPDATE dbo.ChiTietDoiTra
           SET DuDieuKienTaiBan=1, TinhTrang=N'Da kiem tra - du dieu kien tai ban'
         WHERE MaChiTietDT=@ChiTietID;
        UPDATE dbo.PhieuDoiTra
           SET TrangThai='HOAN_TAT', MaNVDuyet=@MaNVDuyet,
               NgayDuyet=COALESCE(NgayDuyet,SYSDATETIME()), NgayHoanTat=SYSDATETIME()
         WHERE SoPhieuDT=@SoPhieuDT;
        SET @KetQua=N'DA_HOAN_TAT_MOI';
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

CREATE   PROCEDURE dbo.usp_HoanTatDoiTraVaDiem
    @SoPhieuDT VARCHAR(30), @MaNVDuyet VARCHAR(20),
    @DaKiemTraHang BIT, @XacNhanKhongNgoaiLe BIT,
    @KetQua NVARCHAR(40)=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    IF DB_NAME()<>N'FashionStoreDB' THROW 57030,N'FashionStoreDB database required.',1;
    DECLARE @TienHoan DECIMAL(18,2),@TienThu DECIMAL(18,2),@HinhThuc VARCHAR(20),
            @KQT NVARCHAR(30),@KQD NVARCHAR(40);
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT @TienHoan=SoTienHoan,@TienThu=SoTienThuThem,@HinhThuc=HinhThucXuLy
        FROM dbo.PhieuDoiTra WHERE SoPhieuDT=@SoPhieuDT;
        IF @HinhThuc IS NULL THROW 57031,N'Unknown return request.',1;
        IF @HinhThuc='DOI' AND @TienHoan=0 AND @TienThu=0
            EXEC dbo.usp_HoanTatDoiHangNgangGia @SoPhieuDT=@SoPhieuDT,
                 @MaNVDuyet=@MaNVDuyet,@DaKiemTraHang=@DaKiemTraHang,
                 @XacNhanKhongNgoaiLe=@XacNhanKhongNgoaiLe,@KetQua=@KQT OUTPUT;
        ELSE
            EXEC dbo.usp_HoanTatDoiTraCoTien @SoPhieuDT=@SoPhieuDT,
                 @MaNVDuyet=@MaNVDuyet,@DaKiemTraHang=@DaKiemTraHang,
                 @XacNhanKhongNgoaiLe=@XacNhanKhongNgoaiLe,@KetQua=@KQT OUTPUT;
        EXEC dbo.usp_DieuChinhDiemDoiTra @SoPhieuDT=@SoPhieuDT,@KetQua=@KQD OUTPUT;
        SET @KetQua=CASE WHEN @KQT=N'DA_HOAN_TAT' AND @KQD=N'DA_XU_LY_TRUOC'
                        THEN N'DA_HOAN_TAT' ELSE N'DA_HOAN_TAT_MOI' END;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

CREATE   PROCEDURE dbo.usp_HuyDonOnline
    @SoHD VARCHAR(30),
    @MaNV VARCHAR(20) = NULL,
    @LyDo NVARCHAR(500) = NULL,
    @KetQua NVARCHAR(30) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF DB_NAME() <> N'FashionStoreDB'
        THROW 54100, N'Procedure requires FashionStoreDB.', 1;
    IF @SoHD IS NULL OR LTRIM(RTRIM(@SoHD)) = ''
        THROW 54101, N'SoHD must be provided.', 1;

    DECLARE @Loai VARCHAR(10), @TrangThai VARCHAR(20),
            @Giao VARCHAR(20), @ThanhToan VARCHAR(20), @SoDong INT;
    DECLARE @BienDong TABLE (
        MaSKU VARCHAR(40) NOT NULL PRIMARY KEY,
        SoLuongThayDoi INT NOT NULL,
        TonSau INT NOT NULL
    );
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT @Loai=LoaiHoaDon, @TrangThai=TrangThaiHoaDon,
               @Giao=TrangThaiGiaoHang, @ThanhToan=TrangThaiThanhToan
        FROM dbo.HoaDon WITH (UPDLOCK, HOLDLOCK)
        WHERE SoHD=@SoHD;
        IF @Loai IS NULL
            THROW 54102, N'Invoice does not exist.', 1;
        IF @Loai <> 'ONLINE'
            THROW 54103, N'Only ONLINE invoices are supported.', 1;
        IF @MaNV IS NOT NULL AND NOT EXISTS
            (SELECT 1 FROM dbo.NhanVien WHERE MaNV=@MaNV AND TrangThai=1)
            THROW 54104, N'Employee does not exist or is disabled.', 1;
        SELECT @SoDong=COUNT(*) FROM dbo.ChiTietHoaDon WHERE SoHD=@SoHD;

        IF @TrangThai='HUY'
        BEGIN
            -- Do not silently mask previously canceled orders with inconsistent shipping states.
            IF @Giao <> 'HUY'
                THROW 54115, N'Legacy canceled invoice has inconsistent shipping status; review manually.', 1;
            IF EXISTS (SELECT 1 FROM dbo.LichSuTonKho ls
                       WHERE ls.MaChungTu=@SoHD AND ls.Nguon='BAN')
            BEGIN
                IF EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon ct
                    WHERE ct.SoHD=@SoHD AND (
                       NOT EXISTS (SELECT 1 FROM dbo.LichSuTonKho ls
                         WHERE ls.MaChungTu=@SoHD AND ls.MaSKU=ct.MaSKU
                           AND ls.Nguon='BAN' AND ls.SoLuongThayDoi=-ct.SoLuong)
                       OR NOT EXISTS (SELECT 1 FROM dbo.LichSuTonKho ls
                         WHERE ls.MaChungTu=@SoHD AND ls.MaSKU=ct.MaSKU
                           AND ls.Nguon='HUY_DON' AND ls.SoLuongThayDoi=ct.SoLuong)))
                   OR EXISTS (SELECT 1 FROM dbo.LichSuTonKho ls
                         WHERE ls.MaChungTu=@SoHD AND ls.Nguon IN ('BAN','HUY_DON')
                           AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon ct
                            WHERE ct.SoHD=@SoHD AND ct.MaSKU=ls.MaSKU))
                    THROW 54105, N'Canceled invoice has inconsistent stock ledger.', 1;
            END
            ELSE IF EXISTS (SELECT 1 FROM dbo.LichSuTonKho ls
                            WHERE ls.MaChungTu=@SoHD AND ls.Nguon='HUY_DON')
                    THROW 54106, N'Cancellation ledger exists without prior deduction.', 1;
            SET @KetQua=N'DA_HUY';
            COMMIT TRANSACTION;
            RETURN;
        END;

        IF @TrangThai NOT IN ('MOI','XAC_NHAN','DANG_XU_LY')
            THROW 54107, N'Order cannot be canceled at this status.', 1;
        IF @Giao NOT IN ('CHUA_GIAO','CHO_XAC_NHAN','DANG_CHUAN_BI')
            THROW 54108, N'Shipped/delivered order must follow return workflow.', 1;
        -- Prevent canceling a prepaid order without financial refund handling.
        IF @ThanhToan NOT IN ('CHUA_THANH_TOAN','THAT_BAI')
            THROW 54109, N'Paid/refunded order needs a separate refund workflow before cancellation.', 1;

        IF @TrangThai='MOI'
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.LichSuTonKho
                       WHERE MaChungTu=@SoHD AND Nguon IN ('BAN','HUY_DON'))
                THROW 54110, N'New order unexpectedly has stock movement history.', 1;
        END
        ELSE
        BEGIN
            IF @SoDong=0
                THROW 54111, N'Confirmed invoice has no items.', 1;
            IF EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon ct
                WHERE ct.SoHD=@SoHD AND NOT EXISTS (
                   SELECT 1 FROM dbo.LichSuTonKho ls
                   WHERE ls.MaChungTu=@SoHD AND ls.MaSKU=ct.MaSKU
                      AND ls.Nguon='BAN' AND ls.SoLuongThayDoi=-ct.SoLuong))
               OR EXISTS (SELECT 1 FROM dbo.LichSuTonKho ls
                      WHERE ls.MaChungTu=@SoHD AND ls.Nguon='BAN'
                        AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon ct
                            WHERE ct.SoHD=@SoHD AND ct.MaSKU=ls.MaSKU))
                THROW 54112, N'Confirmed order has no complete BAN ledger.', 1;
            IF EXISTS (SELECT 1 FROM dbo.LichSuTonKho
                       WHERE MaChungTu=@SoHD AND Nguon='HUY_DON')
                THROW 54113, N'Cancellation stock restore already recorded.', 1;

            -- Overflow-aware restock, all-or-nothing.
            UPDATE bt WITH (UPDLOCK)
               SET SoLuongTonKho=bt.SoLuongTonKho+ct.SoLuong
               OUTPUT inserted.MaSKU,
                      inserted.SoLuongTonKho-deleted.SoLuongTonKho,
                      inserted.SoLuongTonKho
                 INTO @BienDong(MaSKU,SoLuongThayDoi,TonSau)
            FROM dbo.BienTheSanPham AS bt
            JOIN dbo.ChiTietHoaDon AS ct ON ct.MaSKU=bt.MaSKU AND ct.SoHD=@SoHD
            WHERE CAST(bt.SoLuongTonKho AS BIGINT)+ct.SoLuong<=2147483647;
            IF (SELECT COUNT(*) FROM @BienDong) <> @SoDong
                THROW 54114, N'Stock restoration failed (SKU missing or overflow).', 1;

            INSERT dbo.LichSuTonKho
                (MaSKU,MaNV,Nguon,SoLuongThayDoi,TonSau,MaChungTu,GhiChu)
            SELECT MaSKU,@MaNV,'HUY_DON',SoLuongThayDoi,TonSau,@SoHD,
                   N'ONLINE: restore stock once on cancellation before shipment'
            FROM @BienDong;
        END;

        UPDATE dbo.HoaDon
           SET TrangThaiHoaDon='HUY', TrangThaiGiaoHang='HUY'
        WHERE SoHD=@SoHD;
        INSERT dbo.LichSuTrangThaiDonHang
            (SoHD,LoaiTrangThai,TrangThaiCu,TrangThaiMoi,MaNV,GhiChu)
        VALUES (@SoHD,'DON_HANG',@TrangThai,'HUY',@MaNV,
                LEFT(COALESCE(@LyDo,N'Customer or staff canceled before shipment'),500)),
               (@SoHD,'GIAO_HANG',@Giao,'HUY',@MaNV,
                LEFT(COALESCE(@LyDo,N'Shipping canceled before shipment'),500));

        SET @KetQua=CASE WHEN @TrangThai='MOI' THEN N'DA_HUY_CHUA_TRU_KHO'
                         ELSE N'DA_HUY_DA_HOAN_KHO' END;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

CREATE   PROCEDURE dbo.usp_XacNhanDonOnline
    @SoHD VARCHAR(30),
    @MaNV VARCHAR(20) = NULL,
    @KetQua NVARCHAR(30) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF DB_NAME() <> N'FashionStoreDB'
        THROW 54002, N'Procedure requires FashionStoreDB.', 1;
    IF @SoHD IS NULL OR LTRIM(RTRIM(@SoHD)) = ''
        THROW 54003, N'SoHD must be provided.', 1;

    DECLARE @Loai VARCHAR(10), @TrangThai VARCHAR(20),
            @Giao VARCHAR(20), @ThanhToan VARCHAR(20), @SoDong INT;
    DECLARE @BienDong TABLE (
        MaSKU VARCHAR(40) NOT NULL PRIMARY KEY,
        SoLuongThayDoi INT NOT NULL,
        TonSau INT NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;
        -- Serialize operations on the SAME invoice across concurrent Web/WinForms calls.
        SELECT @Loai=LoaiHoaDon, @TrangThai=TrangThaiHoaDon,
               @Giao=TrangThaiGiaoHang, @ThanhToan=TrangThaiThanhToan
        FROM dbo.HoaDon WITH (UPDLOCK, HOLDLOCK)
        WHERE SoHD=@SoHD;

        IF @Loai IS NULL
            THROW 54004, N'Invoice does not exist.', 1;
        IF @Loai <> 'ONLINE'
            THROW 54005, N'Only ONLINE invoices are supported.', 1;
        IF @MaNV IS NOT NULL AND NOT EXISTS
            (SELECT 1 FROM dbo.NhanVien WHERE MaNV=@MaNV AND TrangThai=1)
            THROW 54006, N'Employee does not exist or is disabled.', 1;
        SELECT @SoDong=COUNT(*) FROM dbo.ChiTietHoaDon WHERE SoHD=@SoHD;
        IF @SoDong=0
            THROW 54007, N'Invoice has no items.', 1;

        -- Never silently accept a half-written or inconsistent ledger.
        IF @TrangThai IN ('XAC_NHAN','DANG_XU_LY','HOAN_TAT')
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon AS ct
                       WHERE ct.SoHD=@SoHD AND NOT EXISTS (
                           SELECT 1 FROM dbo.LichSuTonKho AS ls
                           WHERE ls.Nguon='BAN' AND ls.MaChungTu=@SoHD
                             AND ls.MaSKU=ct.MaSKU AND ls.SoLuongThayDoi=-ct.SoLuong))
               OR EXISTS (SELECT 1 FROM dbo.LichSuTonKho AS ls
                       WHERE ls.Nguon='BAN' AND ls.MaChungTu=@SoHD
                         AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietHoaDon AS ct
                           WHERE ct.SoHD=@SoHD AND ct.MaSKU=ls.MaSKU))
               OR EXISTS (SELECT 1 FROM dbo.LichSuTonKho
                       WHERE MaChungTu=@SoHD AND Nguon='HUY_DON')
                THROW 54008, N'Existing order stock ledger is inconsistent; do not deduct again.', 1;
            SET @KetQua=N'DA_XAC_NHAN';
            COMMIT TRANSACTION;
            RETURN;
        END;

        IF @TrangThai <> 'MOI'
            THROW 54009, N'Only a new (MOI) invoice can be confirmed.', 1;
        IF @Giao NOT IN ('CHUA_GIAO','CHO_XAC_NHAN')
            THROW 54010, N'Invoice has already advanced to shipping.', 1;
        IF @ThanhToan NOT IN ('CHUA_THANH_TOAN','DA_THANH_TOAN')
            THROW 54011, N'Payment state does not allow confirmation.', 1;
        IF EXISTS (SELECT 1 FROM dbo.LichSuTonKho
                   WHERE MaChungTu=@SoHD AND Nguon IN ('BAN','HUY_DON'))
            THROW 54012, N'Stock ledger already exists for this new invoice.', 1;

        -- Atomic conditional stock update; ROWCOUNT verifies ALL SKUs succeeded.
        -- UPDLOCK & UPDATE locks protect against concurrent sales of final units.
        UPDATE bt WITH (UPDLOCK)
           SET SoLuongTonKho=bt.SoLuongTonKho-ct.SoLuong
           OUTPUT inserted.MaSKU,
                  inserted.SoLuongTonKho-deleted.SoLuongTonKho,
                  inserted.SoLuongTonKho
             INTO @BienDong(MaSKU,SoLuongThayDoi,TonSau)
        FROM dbo.BienTheSanPham AS bt
        INNER JOIN dbo.ChiTietHoaDon AS ct ON ct.MaSKU=bt.MaSKU AND ct.SoHD=@SoHD
        INNER JOIN dbo.SanPham AS sp ON sp.MaSP=bt.MaSP
        WHERE bt.TrangThai=1 AND sp.TrangThai=1
          AND bt.SoLuongTonKho>=ct.SoLuong;

        IF (SELECT COUNT(*) FROM @BienDong) <> @SoDong
            THROW 54013, N'Insufficient stock, invalid SKU, or inactive product; no stock deducted.', 1;

        INSERT dbo.LichSuTonKho
            (MaSKU,MaNV,Nguon,SoLuongThayDoi,TonSau,MaChungTu,GhiChu)
        SELECT MaSKU,@MaNV,'BAN',SoLuongThayDoi,TonSau,@SoHD,
               N'ONLINE: stock deducted on order confirmation (Option B)'
        FROM @BienDong;

        UPDATE dbo.HoaDon
           SET TrangThaiHoaDon='XAC_NHAN', TrangThaiGiaoHang='DANG_CHUAN_BI'
        WHERE SoHD=@SoHD;

        INSERT dbo.LichSuTrangThaiDonHang
            (SoHD,LoaiTrangThai,TrangThaiCu,TrangThaiMoi,MaNV,GhiChu)
        VALUES (@SoHD,'DON_HANG','MOI','XAC_NHAN',@MaNV,N'Confirmed ONLINE order'),
               (@SoHD,'GIAO_HANG',@Giao,'DANG_CHUAN_BI',@MaNV,N'Packing preparation');

        SET @KetQua=N'DA_XAC_NHAN_MOI';
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
